import streamlit as st
import pandas as pd
import urllib.parse
import random

# ==============================================================================
# ⚙️ MODELAGEM VISUAL (DARK MODE & GLASSMORPHISM)
# ==============================================================================
st.set_page_config(page_title="SuperRadar Dark", layout="wide", page_icon="🏆")

# CSS Avançado para transformar o Streamlit em um App Moderno
st.markdown("""
    <style>
    /* Fundo do App */
    .stApp {
        background-color: #0E1117;
        color: #FFFFFF;
    }
    
    /* Ajuste de Fontes e Cores Gerais */
    h1, h2, h3, p, span, label {
        color: #FFFFFF !important;
    }

    /* Estilo dos Cards de Oferta (Glassmorphism) */
    .offer-card {
        background: rgba(28, 31, 38, 0.8);
        padding: 20px;
        border-radius: 20px;
        border: 1px solid rgba(255, 255, 255, 0.1);
        border-left: 6px solid #00C853;
        margin-bottom: 20px;
        box-shadow: 0 4px 15px rgba(0,0,0,0.3);
        transition: transform 0.3s ease;
    }
    .offer-card:hover {
        transform: translateY(-5px);
        border-left: 6px solid #FFD700;
    }

    /* Badge de Melhor Preço */
    .best-price-badge {
        background: linear-gradient(45deg, #FFD700, #FFA500);
        color: #000 !important;
        padding: 4px 12px;
        border-radius: 10px;
        font-weight: bold;
        font-size: 12px;
        display: inline-block;
        margin-bottom: 10px;
    }

    /* Tarja de Notícias (Marquee) */
    .marquee-box {
        background: linear-gradient(90deg, #16a34a, #00C853);
        color: white !important;
        padding: 12px;
        border-radius: 15px;
        font-weight: bold;
        text-align: center;
        margin-bottom: 30px;
        box-shadow: 0 0 20px rgba(0, 200, 83, 0.4);
    }

    /* Botões Customizados */
    .stButton>button {
        background-color: #00C853 !important;
        color: white !important;
        border-radius: 12px !important;
        border: none !important;
        font-weight: bold !important;
        transition: 0.3s !important;
    }
    .stButton>button:hover {
        background-color: #FFD700 !important;
        color: #000 !important;
    }
    
    /* Inputs */
    .stTextInput>div>div>input, .stSelectbox>div>div {
        background-color: #1C1F26 !important;
        color: white !important;
        border: 1px solid #333 !important;
        border-radius: 10px !important;
    }
    </style>
    """, unsafe_allow_html=True)

URL_SISTEMA = "https://meu-radar-ofertas.streamlit.app"

# ==============================================================================
# 🗄️ BANCO DE DADOS SOCIAL
# ==============================================================================
if 'db_promocoes' not in st.session_state:
    st.session_state.db_promocoes = [
        {"produto": "Arroz 5kg", "preco": 21.50, "loja": "Super Hiper", "tipo": "dia", "pagamento": "Pix", "curtidas": 150},
        {"produto": "Feijão 1kg", "preco": 6.90, "loja": "Mercadinho Zé", "tipo": "semana", "pagamento": "Dinheiro", "curtidas": 80},
        {"produto": "Leite 1L", "preco": 4.10, "loja": "EcoPreço", "tipo": "dia", "pagamento": "Cartão", "curtidas": 210},
    ]

# ==============================================================================
# 📱 NAVEGAÇÃO
# ==============================================================================
st.sidebar.markdown("<h1 style='text-align: center; color: #00C853;'>💎 SuperRadar</h1>", unsafe_allow_html=True)
st.sidebar.markdown("---")
app_mode = st.sidebar.selectbox("Painel de Controle", ["👥 Comunidade", "🔍 Comparador", "🏪 Lojista", "🏆 Ranking Social", "💰 Planos"])

